			} catch (Exception ignored) {
				// Ignore
			}
		}
		clearTypes(annotation.annotationType, context);
		List<JCExpression> args = annotation.args;
		if (args != null) {
			for (List<JCExpression> cursor = args; cursor.nonEmpty(); cursor = cursor.tail) {
				JCExpression arg = cursor.head;
				if (arg instanceof JCAssign) {
					JCAssign assign = (JCAssign) arg;
					JCExpression lhs = assign.lhs;
					JCExpression rhs = assign.rhs;
					clearTypes(lhs, context);
					clearTypes(rhs, context);
				} else {
					clearTypes(arg, context);
				}
			}
		}
		return;
	}

	if (tree instanceof JCNewArray) {
		JCNewArray array = (JCNewArray) tree;
		JCExpression elemType = array.elemtype;
		List<JCExpression> dims = array.dims;
		List<JCExpression> elems = array.elems;
		clearTypes(elemType, context);
		if (dims != null) {
			for (List<JCExpression> cursor = dims; cursor.nonEmpty(); cursor = cursor.tail) {
				JCExpression dim = cursor.head;
				clearTypes(dim, context);
			}
		}
		if (elems != null) {
			for (List<JCExpression> cursor = elems; cursor.nonEmpty(); cursor = cursor.tail) {
				JCExpression elem = cursor.head;
				clearTypes(elem, context);
			}
		}
		return;
	}

	if (tree instanceof JCAssign) {
		JCAssign assign = (JCAssign) tree;
		JCExpression lhs = assign.lhs;
		JCExpression rhs = assign.rhs;
		clearTypes(lhs, context);
		clearTypes(rhs, context);
		return;
	}

	if (tree instanceof JCFieldAccess) {
		JCFieldAccess access = (JCFieldAccess) tree;
		JCExpression selected = access.selected;
		access.sym = null;
		clearTypes(selected, context);
		return;
	}

	if (tree instanceof JCIdent) {
		JCIdent ident = (JCIdent) tree;
		ident.sym = null;
		return;
	}

	if (spec >= 8 && JCAnnotatedTypeReflect.is(tree)) {
		List<JCAnnotation> typeAnnotations = JCAnnotatedTypeReflect.getAnnotations(tree);
		if (typeAnnotations != null) {
			for (List<JCAnnotation> cursor = typeAnnotations; cursor.nonEmpty(); cursor = cursor.tail) {
				JCAnnotation typeAnnotation = cursor.head;
				clearTypes(typeAnnotation, context);
			}
		}
		JCExpression underlyingType = JCAnnotatedTypeReflect.getUnderlyingType(tree);
		clearTypes(underlyingType, context);
		return;
	}

	final JCTree current = tree;
	tree.accept(new TreeScanner() {
		@Override public void scan(JCTree child) {
			if (child == current) super.scan(child);
			else clearTypes(child, context);
		}
	});
